const zlib = require('zlib');
const PDFDocument = require('/tmp/docx2pdf/node_modules/pdfkit');

// --- Extract text from .docx ---
const buf = fs.readFileSync('/workspace/testbed/docs/customer_report.docx');
let eocdOffset = -1;
for (let i = buf.length - 22; i >= 0; i--) {
  if (buf.readUInt32LE(i) === 0x06054b50) { eocdOffset = i; break; }
}
const cdOffset = buf.readUInt32LE(eocdOffset + 16);
const cdCount = buf.readUInt16LE(eocdOffset + 10);

let offset = cdOffset;
let xml = '';
for (let i = 0; i < cdCount; i++) {
  const compMethod = buf.readUInt16LE(offset + 10);
  const compSize = buf.readUInt32LE(offset + 20);
  const fnLen = buf.readUInt16LE(offset + 28);
  const exLen = buf.readUInt16LE(offset + 30);
  const cmLen = buf.readUInt16LE(offset + 32);
  const localHeaderOffset = buf.readUInt32LE(offset + 42);
  const fileName = buf.toString('utf8', offset + 46, offset + 46 + fnLen);
  if (fileName === 'word/document.xml') {
    const lhFnLen = buf.readUInt16LE(localHeaderOffset + 26);
    const lhExLen = buf.readUInt16LE(localHeaderOffset + 28);
    const dataStart = localHeaderOffset + 30 + lhFnLen + lhExLen;
    const compData = buf.slice(dataStart, dataStart + compSize);
    xml = compMethod === 0 ? compData.toString('utf8') : zlib.inflateRawSync(compData).toString('utf8');
    break;
  }
  offset += 46 + fnLen + exLen + cmLen;
}

// Parse paragraphs
const parts = xml.split('</w:p>');
const lines = [];
for (const part of parts) {
  const texts = [];
  const re = /<w:t[^>]*>([^<]*)<\\/w:t>/g;
  let m;
  while ((m = re.exec(part)) !== null) texts.push(m[1]);
  lines.push(texts.length > 0 ? texts.join('') : '');
}

// Detect bold runs per paragraph
function parseParagraph(part) {
  const runs = [];
  const runRe = /<w:r>(.*?)<\\/w:r>|<w:r .*?>(.*?)<\\/w:r>/gs;
  let rm;
  while ((rm = runRe.exec(part)) !== null) {
    const runXml = rm[1] || rm[2];
    const isBold = /<w:b\\s*\\/>/.test(runXml) || /<w:b>/.test(runXml);
    const texts = [];
    const tre = /<w:t[^>]*>([^<]*)<\\/w:t>/g;
    let tm;
    while ((tm = tre.exec(runXml)) !== null) texts.push(tm[1]);
    if (texts.length > 0) runs.push({ text: texts.join(''), bold: isBold });
  }
  return runs;
}

// --- Generate PDF ---
const doc = new PDFDocument({ margin: 50, size: 'A4' });
const outPath = '/workspace/testbed/docs/customer_report.pdf';
const stream = fs.createWriteStream(outPath);
doc.pipe(stream);

const boldFont = 'Helvetica-Bold';
const normalFont = 'Helvetica';

for (let pi = 0; pi < parts.length - 1; pi++) {
  const part = parts[pi];
  const runs = parseParagraph(part);
  if (runs.length === 0) {
    doc.moveDown(0.3);
    continue;
  }
  // Check if it's a title (first non-empty paragraph)
  const fullText = runs.map(r => r.text).join('');
  const isTitle = fullText === 'Customer Activity Report';
  const isCustomerName = !fullText.includes(':') && !fullText.includes('—') && !fullText.startsWith('  ') && !isTitle && runs.some(r => r.bold);

  if (isTitle) {
    doc.font(boldFont).fontSize(18).text(fullText, { align: 'center' });
    doc.moveDown(0.8);
  } else if (isCustomerName) {
    doc.moveDown(0.4);
    doc.font(boldFont).fontSize(12).text(fullText);
  } else {
    const fontSize = 10;
    doc.fontSize(fontSize);
    for (let ri = 0; ri < runs.length; ri++) {
      const r = runs[ri];
      doc.font(r.bold ? boldFont : normalFont);
      const opts = ri < runs.length - 1 ? { continued: true } : {};
      doc.text(r.text, opts);
    }
  }
}

doc.end();
stream.on('finish', () => {
  console.log('PDF created: ' + outPath);
  console.log('Size: ' + fs.statSync(outPath).size + ' bytes');
});
